 async function loadEthereumPortfolio(e){
  e.preventDefault();setPortfolioError('');setPortfolioRows([]);
  const addresses=Array.from(new Set(portfolioAddresses.split(/[\\s,;]+/).map(x=>x.trim()).filter(Boolean)));
  if(!addresses.length){setPortfolioError('Enter at least one public Ethereum address.');return;}
  if(addresses.length>10){setPortfolioError('For provider reliability, check up to 10 addresses per batch.');return;}
  const invalid=addresses.find(x=>!/^0x[a-fA-F0-9]{40}$/.test(x));
  if(invalid){setPortfolioError('Invalid Ethereum address format: '+short(invalid,10,6));return;}
  setPortfolioBusy(true);
  try{
   const c=CHAINS.eth;
   const rows=await Promise.all(addresses.map(async address=>{
    const nativeRaw=await evmRpc('eth','eth_getBalance',[address,'latest']);
    let tokenRaw=null;
    try{tokenRaw=await evmRpc('eth','eth_call',[{to:c.usdt,data:'0x70a08231'+address.slice(2).toLowerCase().padStart(64,'0')},'latest']);}catch(_){}
    return {address,eth:formatUnits(nativeRaw,18,8),usdt:tokenRaw===null?'Unavailable':formatUnits(tokenRaw,6,6),url:c.wallet+address};
   }));
   setPortfolioRows(rows);
  }catch(err){setPortfolioError(err.message||'Could not retrieve portfolio balances.');}
  finally{setPortfolioBusy(false);}
 }
