 if(!ownerToken)return <div className="owner-auth-screen"><div className="owner-auth-orb owner-auth-orb-one"/><div className="owner-auth-orb owner-auth-orb-two"/><section className="owner-auth-card"><div className="owner-auth-brand"><div className="brand-logo">V<span>•</span></div><div><b>VexaTrade</b><small>TRANSACTION TOOLS</small></div></div><div className="owner-auth-icon"><ShieldCheck size={24}/></div><label className="eyebrow">RESTRICTED OWNER WORKSPACE</label><h1>Sign in to Transaction Tools</h1><p className="owner-auth-subtitle">Authenticate with your VexaTrade Admin account before opening any dashboard, wallet lookup, transfer, integration, or transaction tool.</p><form className="owner-auth-form" onSubmit={e=>{e.preventDefault();connectOwner();}}><label><span><Mail size={14}/> Admin email</span><input type="email" required autoComplete="username" value={loginEmail} onChange={e=>setLoginEmail(e.target.value)} placeholder="admin@example.com"/></label><label><span><KeyRound size={14}/> Password</span><input type="password" required autoComplete="current-password" value={loginPassword} onChange={e=>setLoginPassword(e.target.value)} placeholder="Enter your admin password"/></label><button className="primary full" disabled={transferLoading}>{transferLoading?<><RefreshCw className="spin" size={15}/> Verifying owner access…</>:<><ShieldCheck size={16}/> Sign in securely</>}</button></form>{transferMessage&&<p className={'owner-auth-message '+(/successfully|connected/i.test(transferMessage)?'success':'')} role="status">{transferMessage}</p>}<div className="owner-auth-security"><ShieldCheck size={15}/><span>Credentials are checked by the VexaTrade Admin API over HTTPS. The session token stays in memory only and is cleared when you sign out or reload. Never enter a seed phrase or private key.</span></div><div className="owner-auth-footer"><span><i/> Owner authentication required</span><span>VexaTrade Transaction Tools</span></div></section></div>;
